html,
body {
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: -3rem;
  background: var(--surface);
  color: var(--text);
  padding: 0.5rem 0.875rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  text-decoration: none;
  z-index: 1000;
  transition: top 0.15s ease;
}
.skip-link:focus {
  top: 0.75rem;
}

/* ----- Header ----- */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.site-header__inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0.875rem 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  text-decoration: none;
  color: var(--text);
  font-weight: 600;
}
.brand__mark {
  color: var(--primary);
  font-size: 1.15rem;
}
.nav-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.nav-list a {
  display: inline-block;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  text-decoration: none;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.nav-list a:hover {
  color: var(--text);
  background: var(--surface-2);
}
.nav-list a[aria-current="page"] {
  color: var(--text);
  background: var(--surface-2);
  font-weight: 500;
}

/* ----- Main / preview ----- */
main {
  max-width: 980px;
  margin: 0 auto;
  padding: 1.5rem 1.25rem 4rem;
}

.breadcrumb ol {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin: 0 0 1rem;
  padding: 0;
  list-style: none;
  color: var(--text-muted);
  font-size: 0.875rem;
}
.breadcrumb li + li::before {
  content: "/";
  margin-right: 0.4rem;
  color: var(--text-muted);
}
.breadcrumb a {
  color: var(--text-muted);
  text-decoration: none;
}
.breadcrumb a:hover {
  color: var(--text);
  text-decoration: underline;
}
.breadcrumb [aria-current="page"] {
  color: var(--text);
}

.preview__title {
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  margin: 0 0 0.25rem;
  letter-spacing: -0.01em;
}
.preview__meta {
  margin: 0 0 1.25rem;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.preview__figure {
  margin: 0 0 1.25rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}
.preview__image {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  background: var(--surface-2);
}
.preview__caption {
  padding: 0.875rem 1.125rem;
  color: var(--text-muted);
  font-size: 0.9rem;
  border-top: 1px solid var(--border);
}

.preview__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.625rem;
}

/* ----- Buttons ----- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.625rem 1.125rem;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  font: inherit;
  font-weight: 500;
  font-size: 0.95rem;
  cursor: pointer;
  transition: background-color 0.12s ease, border-color 0.12s ease, color 0.12s ease, transform 0.05s ease;
  min-height: 40px;
}
.btn:active {
  transform: translateY(1px);
}

.btn--secondary {
  background: var(--surface);
  color: var(--text);
  border-color: var(--border);
  box-shadow: var(--shadow-sm);
}
.btn--secondary:hover {
  background: var(--surface-2);
}

.btn--danger {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}
.btn--danger:hover {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
}

/* ----- Status ----- */
.status {
  margin-top: 1rem;
  min-height: 1.25rem;
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* ----- Dialog ----- */
.dialog {
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  max-width: min(440px, calc(100vw - 2rem));
  width: 100%;
  box-shadow: var(--shadow-lg);
}
.dialog::backdrop {
  background: rgba(8, 12, 20, 0.55);
  backdrop-filter: blur(2px);
}
.dialog[open] {
  animation: dialog-in 0.15s ease-out;
}
@keyframes dialog-in {
  from { opacity: 0; transform: translateY(8px) scale(0.98); }
  to   { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[open] { animation: none; }
}

.dialog__form {
  margin: 0;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.dialog__heading {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.dialog__body {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.dialog__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.5rem;
  margin-top: 0.5rem;
}

@media (forced-colors: active) {
  .btn,
  .dialog,
  .preview__figure,
  .site-header {
    border-color: CanvasText;
  }
  .btn--danger {
    background: ButtonFace;
    color: ButtonText;
  }
}
